INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 11, 'theory', 'Quiz: search trees');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 0, 'A search tree is valid if...', '["each node is larger than its left child and smaller than its right child", "for each node, all keys of the left subtree are smaller and all keys of the right subtree are larger", "the root is the median of all keys", "the tree height is at most the logarithm of the number of nodes"]', 1, 'The rule covers all descendants, not just the children. That is why the check is written with bounds passed down.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 1, 'Which key replaces a deleted node with two children?', '["The left child", "The root of the tree", "The successor, the minimum of the right subtree", "A random leaf"]', 2, 'The successor is the closest key in value: in its place the order is preserved. It is then removed from its old place, where it has at most one child.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 2, 'Keys are inserted into a search tree in ascending order (1, 2, 3, ..., n). What do we get?', '["A perfectly balanced tree", "A chain of height n: search, insertion, and deletion are O(n)", "A tree of height log n", "An insertion error"]', 1, 'Each new key is larger than all the others and goes to the right, so the tree degenerates into a linked list. Ordered data needs self-balancing trees.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 3, 'What stays unchanged in a rotation?', '["The tree height", "The order of keys in the inorder traversal", "The root", "The number of leaves"]', 1, 'A rotation is a local restructuring of a few links: the height and the root change, but the inorder order of keys does not. AVL and red-black trees rely on this.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 4, 'What can a search tree do that a hash table cannot?', '["Look up a key by value", "Find the nearest key and ranges", "Add keys", "Store key-value pairs"]', 1, 'Ordering gives floor and ceiling, the successor, the k-th key, and ranges in time of the height plus the number of answers; a hash table does not keep order.');
